import { Injectable, NotFoundException } from '@nestjs/common';

@Injectable()
export class UserService {
  private data = [
    { id: 1, nama: 'Budi' },
    { id: 2, nama: 'Ani' },
  ];

  semua() {
    return this.data;
  }

  detail(id: number) {
    const item = this.data.find((u) => u.id === id);
    if (!item) throw new NotFoundException('User tidak ditemukan');
    return item;
  }
}
